def most_frequent_artist(songs):
    artist_count = {}

    for song in songs:
        artist = song["artist"]
        artist_count[artist] = artist_count.get(artist, 0) + 1

    most_frequent_artists = [artist for artist, count in artist_count.items() if count == max(artist_count.values())]

    if len(most_frequent_artists) == 1:
        return most_frequent_artists[0]
    else:
        return most_frequent_artists

